state.probe:
static int airoha_npu_probe(struct platform_device *pdev)
{
	struct device *dev = &pdev->dev;
	struct airoha_npu_priv *priv;
	struct airoha_npu *npu;
	struct resource res;
	void __iomem *base;
	int i, irq, err;
	u32 val;

	base = devm_platform_ioremap_resource(pdev, 0);
	if (IS_ERR(base))
		return PTR_ERR(base);

	priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
	if (!priv)
		return -ENOMEM;
	npu = &priv->npu;

	npu->dev = dev;
	npu->ops.ppe_init = airoha_npu_ppe_init;
	npu->ops.ppe_deinit = airoha_npu_ppe_deinit;
	npu->ops.ppe_init_stats = airoha_npu_ppe_stats_setup;
	npu->ops.ppe_flush_sram_entries = airoha_npu_ppe_flush_sram_entries;
	npu->ops.ppe_foe_commit_entry = airoha_npu_foe_commit_entry;
	npu->ops.wlan_init_reserved_memory = airoha_npu_wlan_init_memory;
	npu->ops.wlan_send_msg = airoha_npu_wlan_msg_send;
	npu->ops.wlan_get_msg = airoha_npu_wlan_msg_get;
	npu->ops.wlan_get_queue_addr = airoha_npu_wlan_queue_addr_get;
	npu->ops.wlan_set_irq_status = airoha_npu_wlan_irq_status_set;
	npu->ops.wlan_get_irq_status = airoha_npu_wlan_irq_status_get;
	npu->ops.wlan_enable_irq = airoha_npu_wlan_irq_enable;
	npu->ops.wlan_disable_irq = airoha_npu_wlan_irq_disable;

	npu->regmap = devm_regmap_init_mmio(dev, base, &regmap_config);
	if (IS_ERR(npu->regmap))
		return PTR_ERR(npu->regmap);
	if (airoha_npu_dma_retained(dev))
		return dev_err_probe(dev, -EBUSY, "NPU DMA retirement pending\n");
	priv->dma_lifetime = kzalloc(sizeof(*priv->dma_lifetime), GFP_KERNEL);
	if (!priv->dma_lifetime)
		return -ENOMEM;
	priv->dma_lifetime->dev = get_device(dev);
	err = devm_add_action_or_reset(dev, airoha_npu_dma_cleanup, priv->dma_lifetime);
	if (err)
		return err;

	err = of_reserved_mem_region_to_resource(dev->of_node, 0, &res);
	if (err)
		return err;

	/* Register work cleanup before IRQs, so devres stops producers first. */
	for (i = 0; i < ARRAY_SIZE(npu->cores); i++) {
		struct airoha_npu_core *core = &npu->cores[i];

		spin_lock_init(&core->lock);
		core->npu = npu;
		err = devm_work_autocancel(dev, &core->wdt_work,
					   airoha_npu_wdt_work);
		if (err)
			return err;
	}
	irq = platform_get_irq(pdev, 0);
	if (irq < 0)
		return irq;

	err = devm_request_irq(dev, irq, airoha_npu_mbox_handler,
			       IRQF_SHARED, "airoha-npu-mbox", npu);
	if (err)
		return err;

	for (i = 0; i < ARRAY_SIZE(npu->cores); i++) {
		struct airoha_npu_core *core = &npu->cores[i];

		irq = platform_get_irq(pdev, i + 1);
		if (irq < 0)
			return irq;

		err = devm_request_irq(dev, irq, airoha_npu_wdt_handler,
				       IRQF_SHARED, "airoha-npu-wdt", core);
		if (err)
			return err;
	}

	/* wlan IRQ lines */
	for (i = 0; i < ARRAY_SIZE(npu->irqs); i++) {
		irq = platform_get_irq(pdev, i + ARRAY_SIZE(npu->cores) + 1);
		if (irq < 0)
			return irq;

		npu->irqs[i] = irq;
	}

	err = dma_set_mask_and_coherent(dev, DMA_BIT_MASK(32));
	if (err)
		return err;

	for (i = 0; i < ARRAY_SIZE(npu->cores); i++) {
		struct airoha_npu_core *core = &npu->cores[i];

		core->buf = dma_alloc_coherent(dev, AIROHA_NPU_MBOX_SIZE,
					       &core->addr, GFP_KERNEL);
		if (!core->buf)
			return -ENOMEM;
		priv->dma_lifetime->buffers[i].buf = core->buf;
		priv->dma_lifetime->buffers[i].addr = core->addr;
	}

	err = airoha_npu_run_firmware(priv, base, &res);
	if (err)
		return err;

	regmap_write(npu->regmap, REG_CR_NPU_MIB(10),
		     res.start + NPU_EN7581_FIRMWARE_RV32_MAX_SIZE);
	regmap_write(npu->regmap, REG_CR_NPU_MIB(11), NPU_SRAM_BACKUP_SIZE);
	regmap_write(npu->regmap, REG_CR_NPU_MIB(12), 0);
	regmap_write(npu->regmap, REG_CR_NPU_MIB(21), 1);
	msleep(100);

	/* setting booting address */
	for (i = 0; i < NPU_NUM_CORES; i++)
		regmap_write(npu->regmap, REG_CR_BOOT_BASE(i), res.start);
	usleep_range(1000, 2000);

	/* enable NPU cores */
	regmap_write(npu->regmap, REG_CR_BOOT_CONFIG, 0xff);
	regmap_write(npu->regmap, REG_CR_BOOT_TRIGGER, 0x1);
	msleep(100);

	if (!airoha_npu_wlan_msg_get(npu, 0, WLAN_FUNC_GET_WAIT_NPU_VERSION,
				     &val, sizeof(val), GFP_KERNEL))
		dev_info(dev, "NPU fw version: %0d.%d\n",
			 (val >> 16) & 0xffff, val & 0xffff);

	platform_set_drvdata(pdev, npu);

	return 0;
}

state.retained_cleanup:
static void airoha_npu_dma_cleanup(void *data)
{
	struct airoha_npu_dma_lifetime *life = data;
	unsigned int i;

	/* No physical retirement witness exists yet. Publication errors, detach
	 * and software parking must not release possibly device-owned mailboxes.
	 */
	if (life->exposed) {
		mutex_lock(&airoha_npu_retained_lock);
		list_add_tail(&life->retained, &airoha_npu_retained_dma);
		mutex_unlock(&airoha_npu_retained_lock);
		dev_warn(life->dev, "retaining NPU DMA mailboxes pending retirement proof\n");
		return;
	}
	for (i = 0; i < ARRAY_SIZE(life->buffers); i++)
		if (life->buffers[i].buf)
			dma_free_coherent(life->dev, AIROHA_NPU_MBOX_SIZE,
					  life->buffers[i].buf, life->buffers[i].addr);
	put_device(life->dev);
	kfree(life);
}

state.exposure:
static int airoha_npu_firmware_expose(struct airoha_npu_priv *priv)
{
	struct airoha_npu_dma_lifetime *life = priv->dma_lifetime;
	unsigned int i;

	if (!life || life->exposed)
		return -EBUSY;
	for (i = 0; i < ARRAY_SIZE(life->buffers); i++)
		if (!life->buffers[i].buf)
			return -EINVAL;
	/* Latch before the first copy: a failed write need not have no effect. */
	life->exposed = true;
	__module_get(THIS_MODULE);

	return 0;
}
